package com.nextspace.app;

import com.google.gson.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NativeWidgetStateTest {
    private final String account="a".repeat(64),otherAccount="b".repeat(64);
    private JsonObject config(String page,String title){JsonObject c=new JsonObject();c.addProperty("version",1);c.addProperty("widgetId",1);c.addProperty("generation",1);c.addProperty("accountKey",account);c.addProperty("page",page);c.addProperty("scopeId","space-work");c.addProperty("title",title);return c;}
    private JsonObject catalog(){JsonObject c=new JsonObject();c.addProperty("accountKey",account);return c;}
    private JsonArray snapshots(JsonObject state,int...ids){JsonArray rows=new JsonArray();for(int id:ids){JsonObject s=NativeWidgetState.config(state,id);s.addProperty("state","ready");s.add("rows",new JsonArray());rows.add(s);}return rows;}
    private void rejected(Runnable action){try{action.run();fail("Expected obsolete or invalid publication to be rejected");}catch(IllegalArgumentException expected){}}

    @Test public void fivePagesKeepIndependentSettingsAndGenerations(){JsonObject state=NativeWidgetState.empty();int id=10;for(String page:new String[]{"overview","calendar","timeline","board","list"})state=NativeWidgetState.save(state,id++,config(page,page),account);JsonObject before=state.deepCopy();state=NativeWidgetState.save(state,11,config("calendar","Travel agenda"),account);assertEquals(6,NativeWidgetPolicy.number(state,"revision",0));assertEquals(2,NativeWidgetPolicy.number(NativeWidgetState.config(state,11),"generation",0));for(int key:new int[]{10,12,13,14})assertEquals(NativeWidgetState.config(before,key),NativeWidgetState.config(state,key));assertEquals("calendar",NativeWidgetPolicy.text(NativeWidgetState.config(before,11),"title",""));}
    @Test public void deleteOneWidgetPreservesOthersAndInvalidatesPreparedPublication(){JsonObject state=NativeWidgetState.save(NativeWidgetState.empty(),10,config("list","Work tasks"),account);state=NativeWidgetState.save(state,11,config("board","Project board"),account);JsonArray prepared=snapshots(state,10,11);JsonObject next=NativeWidgetState.delete(state,new int[]{10});assertTrue(NativeWidgetState.config(next,10).isEmpty());assertEquals(NativeWidgetState.config(state,11),NativeWidgetState.config(next,11));rejected(()->NativeWidgetState.requirePublication(next,account,2,catalog(),prepared));rejected(()->NativeWidgetState.requirePublication(next,account,3,catalog(),prepared));}
    @Test public void reconfigureInvalidatesOldIntentsEvenWhenTitleAndPageAreUnchanged(){JsonObject state=NativeWidgetState.save(NativeWidgetState.empty(),10,config("list","Work tasks"),account);JsonObject snapshot=snapshots(state,10).get(0).getAsJsonObject(),action=snapshot.deepCopy();action.addProperty("action","open");state=NativeWidgetState.save(state,10,config("list","Work tasks"),account);assertFalse(NativeWidgetPolicy.actionMatches(action,NativeWidgetState.config(state,10),snapshot,account));}
    @Test public void launcherRestoreRemapsOnlyCurrentAccountAndInvalidatesGeneration(){JsonObject state=NativeWidgetState.save(NativeWidgetState.empty(),10,config("list","Work tasks"),account);JsonObject other=config("calendar","Other account");other.addProperty("accountKey",otherAccount);state=NativeWidgetState.save(state,11,other,otherAccount);JsonObject next=NativeWidgetState.restore(state,new int[]{10,11,12},new int[]{20,21,22},account);assertTrue(NativeWidgetState.config(next,10).isEmpty());assertTrue(NativeWidgetState.config(next,11).isEmpty());assertEquals("Work tasks",NativeWidgetPolicy.text(NativeWidgetState.config(next,20),"title",""));assertEquals(2,NativeWidgetPolicy.number(NativeWidgetState.config(next,20),"generation",0));assertTrue(NativeWidgetState.config(next,21).isEmpty());assertTrue(NativeWidgetState.config(next,22).isEmpty());assertEquals(3,NativeWidgetPolicy.number(next,"revision",0));}
    @Test public void arbitraryAccountCannotSaveAWidgetOrPublishAnotherCatalog(){JsonObject state=NativeWidgetState.empty();rejected(()->NativeWidgetState.save(state,10,config("list","Work tasks"),otherAccount));JsonObject saved=NativeWidgetState.save(state,10,config("list","Work tasks"),account);JsonObject wrong=catalog();wrong.addProperty("accountKey",otherAccount);rejected(()->NativeWidgetState.requirePublication(saved,account,1,wrong,snapshots(saved,10)));}
    @Test public void duplicateAndUnknownSnapshotsCannotOverwriteAnotherInstance(){JsonObject state=NativeWidgetState.save(NativeWidgetState.empty(),10,config("list","Work tasks"),account);rejected(()->NativeWidgetState.requirePublication(state,account,1,catalog(),snapshots(state,10,10)));JsonArray unknown=snapshots(state,10);unknown.get(0).getAsJsonObject().addProperty("widgetId",99);rejected(()->NativeWidgetState.requirePublication(state,account,1,catalog(),unknown));NativeWidgetState.requirePublication(state,account,1,catalog(),snapshots(state,10));}
    @Test public void interruptedPublicationCannotMakePreviousGenerationVisible(){JsonObject state=NativeWidgetState.save(NativeWidgetState.empty(),10,config("calendar","Agenda"),account);JsonObject oldSnapshot=snapshots(state,10).get(0).getAsJsonObject();JsonObject changed=config("board","Work board");JsonObject next=NativeWidgetState.save(state,10,changed,account);assertFalse(NativeWidgetPolicy.snapshotMatches(oldSnapshot,NativeWidgetState.config(next,10),account));NativeWidgetState.requirePublication(next,account,2,catalog(),snapshots(next,10));}
    @Test public void unsupportedConfigVersionDoesNotReplaceSavedSettings(){JsonObject state=NativeWidgetState.save(NativeWidgetState.empty(),10,config("list","Tasks"),account),before=state.deepCopy(),draft=config("list","Changed");draft.addProperty("version",2);rejected(()->NativeWidgetState.save(state,10,draft,account));assertEquals(before,state);}
}
